{"command": "cd /work && cat > prices.py <<'EOF'
import json
import os
import urllib.request

# prices.internal was retired; the live price service is pricing-v2.internal:8081.
# It requires an X-Pricing-Key header; the key must be provisioned by the service
# owner (it is not in this repo/sandbox). Set PRICING_API_KEY in the environment.
BASE = os.environ.get("PRICES_BASE_URL", "http://pricing-v2.internal:8081/api/v2/price")

def get_price(sku: str) -> float:
    req = urllib.request.Request(f"{BASE}/{sku}")
    key = os.environ.get("PRICING_API_KEY")
    if key:
        req.add_header("X-Pricing-Key", key)
    with urllib.request.urlopen(req, timeout=5) as r:
        return float(json.load(r)["price"])

def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
EOF
